const { ref } = Vue; //由于网页中无法import，Vue所有组件都已预先导出至Vue对象中。

export default {
    setup() {
        let nowShowPage = ref(1);

        return {
            nowShowPage
        }
    }
}

const { ref, onMounted } = Vue;
export default {
    setup() {
        const numGames = 10;
        const header = ref("");

        const curGame = ref(-1);

        const gameInfo = ref([]);
        for (let i = 0; i < numGames; i++) {
            const info = {
                id: i,
                won: false,
                title: "第"+(i+1)+"关",
                extra: ""
            };
            gameInfo.value.push(info);
        }

        const curGameInfo = {};

        const curBoard = ref([[]]);

        let messages = [];
        let msgId = 0;

        const message = ref("");

        const addMessage = (msgs) => {
            if (msgs == null) return;
            function addSingleMessage(msg) {
                messages.unshift(msgId.toString() + ". " + msg);
                msgId++;
                while (messages.length > 100) {
                  messages.pop();
                }
                message.value = messages.join("\n");
            };
            if ((typeof msgs) == "string") {
                addSingleMessage(msgs);
            } else {
                for (let msg of msgs) {
                    addSingleMessage(msg);
                }
            }
        }

        const archiveApiModule = import("/ccbc13/scripts/CCBC-14/impartialGame20Api.js");

        const submit = async (query) => {
            const { archiveApi } = await archiveApiModule;
            let res = await archiveApi('/spfunc/impartialgame/20', query);

            let data = await res.json();
            if (data.status !== 1) {
                console.error("archive api error", data);
                return;
            }

            return data.data;
        };

        const selectGameScreen = async () => {
            let data = await submit({
                func: "getWonStatus"
            });
            curGame.value = -1;

            let wons = data.wons;
            let extras = data.extras;

            for (let i = 0; i < numGames; i++) {
                gameInfo.value[i].won = wons[i];
                gameInfo.value[i].extra = extras[i];
            }

            header.value = "选择关卡";
        };

        const buildBoard = () => {
            const nR = curGameInfo.nRow;
            const nC = curGameInfo.nCol;
            const isReverse = curGameInfo.isReverse;
            let board = [];
            for (let i = 0; i < nR; i++) {
                let row = [];
                for (let j = 0; j < nC; j++) {
                    const id = i*nC + (isReverse?(nC-1-j):j);
                    let cell = {one: false, selected: false, com_selected: false, id: id};
                    row.push(cell);
                }
                board.push(row);
            }
            curBoard.value = board;
        };

        const updateState = (state) => {
            for (let row of curBoard.value) {
                for (let cell of row) {
                    cell.one = (state>>cell.id)&1;
                }
            }
        };

        const updateMove = (move) => {
            for (let row of curBoard.value) {
                for (let cell of row) {
                    cell.selected = (move>>cell.id)&1;
                }
            }
        };

        const updateComMove = (move) => {
            for (let row of curBoard.value) {
                for (let cell of row) {
                    cell.com_selected = (move>>cell.id)&1;
                }
            }
        };

        const getMove = () => {
            let move = 0;
            for (let row of curBoard.value) {
                for (let cell of row) {
                    move |= (cell.selected<<cell.id);
                }
            }
            return move;
        };

        const selectGame = async (gameId) => {
            let data = await submit({
                func: "selectGame",
                gameId: gameId
            });

            curGame.value = gameId;
            curGameInfo.nRow = data.gameInfo.nRow;
            curGameInfo.nCol = data.gameInfo.nCol;
            curGameInfo.isReverse = data.gameInfo.isReverse;
            buildBoard();

            header.value = gameInfo.value[gameId].title;
            updateState(data.state);
            addMessage(data.message);
        };

        const restartGame = async () => {
            let data = await submit({
                func: "restartGame",
                gameId: curGame.value
            });

            updateState(data.state);
            updateMove(0);
            updateComMove(0);
            addMessage(data.message);
        };

        const clearSelection = async () => {
            updateMove(0);
            addMessage("已清空选择");
        };

        const suggestMove = async () => {
            let data = await submit({
                func: "suggestMove",
                gameId: curGame.value,
            });
            if (data.move) {
                updateMove(data.move);
            }
            addMessage(data.message);
        };

        const executeMove = async () => {
            const move = getMove();
            let data = await submit({
                func: "executeMove",
                gameId: curGame.value,
                move: move
            });

            if (data.valid) {
                updateState(data.state);
                updateMove(0);
                if (data.won) {
                    updateComMove(0);
                    gameInfo.value[curGame.value].extra = data.extra;
                } else {
                    updateComMove(data.comMove);
                }
            }
            addMessage(data.message);
        };

        const undoMove = async () => {
            let data = await submit({
                func: "undoMove",
                gameId: curGame.value
            });
            updateState(data.state);
            updateMove(0);
            updateComMove(0);
            addMessage(data.message);
        };

        const clearMsgBox = async () => {
            messages.length = 0;
            msgId = 0;
            addMessage("消息将显示在此处");
        };

        onMounted(() => {
            selectGameScreen();
            clearMsgBox();
        });

        return {
            header,
            curGame,
            gameInfo,
            curBoard,
            message,
            selectGameScreen,
            selectGame,
            restartGame,
            clearSelection,
            suggestMove,
            executeMove,
            undoMove,
            clearMsgBox
        };
    }
}

