( function() {
	const bees = [[new Image(), new Image()], [new Image(), new Image()]];
	const wingspeed = 100;
	var speed2a = 60;
	var speed2b = 20;
	var start2a = 30;
	var start2b = 500;
	const lineHeight = 250;
	var size2a = 30;
	var size2b = 10;
	var zoommode = false;
	var zoomedtime = null;
	var zoomtime = null;
	var zoomspeed = 1;
	var zoomed = 0;
	const size3a = 100;
	const size3b = 50;

	function init() {
		bees[0][0].src = "https://static.cipherpuzzles.com/static/images/0ac0538daa184b5481d35ac002e85d9c.svg";
		bees[1][0].src = "https://static.cipherpuzzles.com/static/images/fdb40c12425c4e609299b8de63a51348.svg";
		bees[0][1].src = "https://static.cipherpuzzles.com/static/images/cd78dd18b9aa41ee801f9938953296ab.svg";
		bees[1][1].src = "https://static.cipherpuzzles.com/static/images/b1b9109fc0bc49068bdf0ba709af05d8.svg";
		zoomedtime = new Date();
		stepTime = new Date();
		time5 = new Date();
		start8 = new Date();
		init6();
		window.requestAnimationFrame(draw);
	}
	function drawbee(time, ctx, size=30, color=0, angle=0) {
		let x = Math.round((time.getSeconds() * 1000 + time.getMilliseconds()) / wingspeed);
		let phase = x % 2;
		ctx.save();
		ctx.rotate(angle);
		ctx.translate(-size/2, -size/2);
		ctx.drawImage(bees[color][phase], 0, 0, size, size);
		ctx.restore();
	}
	function drawbeeu(time, ctx, size=30, color=0) {
		drawbee(time, ctx, size, color, angle=0);
	}
	function drawbeer(time, ctx, size=30, color=0) {
		drawbee(time, ctx, size, color, angle=Math.PI/2);
	}
	function drawbeel(time, ctx, size=30, color=0) {
		drawbee(time, ctx, size, color, angle=-Math.PI/2);
	}
	function drawbeed(time, ctx, size=30, color=0) {
		drawbee(time, ctx, size, color, angle=Math.PI);
	}

	const maxangle = Math.PI / 4;
	const height = 250;
	const speed1 = 4;
	function drawbee11(time, ctx) {
		var angle = Math.cos((time.getSeconds() + time.getMilliseconds() / 1000) * speed1) * maxangle;
		if (angle < 0) {
			angle = 0;
		}
		ctx.save();
		ctx.rotate(angle);
		ctx.translate(0, height);
		drawbee(time, ctx);
		ctx.restore();
	}
	function drawbee15(time, ctx) {
		var angle = Math.cos((time.getSeconds() + time.getMilliseconds() / 1000) * speed1)* maxangle;
		if (angle > 0) {
			angle = 0;
		}
		ctx.save();
		ctx.rotate(angle);
		ctx.translate(0, height);
		drawbee(time, ctx);
		ctx.restore();
	}
	function draw1(time) {
		const canvas = document.getElementById("canvas1")
		const ctx = canvas.getContext("2d");
		ctx.clearRect(0, 0, canvas1.width, canvas1.height);
		ctx.save();
		ctx.translate(height, 0); 
		drawbee11(time, ctx);
		ctx.translate(35, height);
		drawbee(time, ctx);
		ctx.translate(35, 0);
		drawbee(time, ctx);
		ctx.translate(35, 0);
		drawbee(time, ctx);
		ctx.translate(35, -height);
		drawbee15(time, ctx);
		ctx.restore();
	}

	function draw2(time) {
		const canvas = document.getElementById("canvas2")
		const ctx = canvas.getContext("2d");
		ctx.clearRect(0, 0, canvas.width, canvas.height);
		ctx.strokeStyle = "rgba(0, 255, 0, 1.0)";
		ctx.fillStyle = "rgba(0, 255, 0, 1.0)";
		ctx.save();

		ctx.beginPath();
		ctx.moveTo(0, lineHeight);
		ctx.lineTo(canvas.width, lineHeight);
		ctx.stroke();

		if (zoommode) {
			let elapsedTime = (time - zoomtime) / 1000;
			let xa = start2b - (start2b - start2a) / zoomspeed * elapsedTime;
			let endb = start2b + (start2b - start2a) / speed2a * speed2b;
			let xb = endb - (endb - start2b) / zoomspeed * elapsedTime;
			let sizemult = 1 + (speed2a/speed2b - 1) / zoomspeed * elapsedTime;
			let size2a_tmp = size2a * sizemult;
			let size2b_tmp = size2b * sizemult;
			ctx.fillStyle = "rgba(255, 0, 0, 1.0)";
			ctx.fillRect(xa - 1,lineHeight - 1,3,3);
			ctx.fillRect(xb - 1,lineHeight - 1,3,3);
			if (xa <= start2a) {
				zoommode = false;
				zoomedtime = time;
				size2a = size2a_tmp;
				size2b = size2b_tmp;
				speed2a *= 1.5;
				speed2b *= 1.5;
