function areAdjacent(a, b) {

    const dx = Math.abs((a % 3) - (b % 3)); // column difference

    const dy = Math.abs(Math.floor(a / 3) - Math.floor(b / 3)); // row difference



    return (dx + dy === 1); // Manhattan distance of 1

}

