const PID = 55;
const PUZZLE_PIDS = [51, 52, 53, 54];
const MESSAGE = "你解出了谜题，那句决定一切的谜底早已到了眼前。它就是：";
const WORDS = ["中心思想", "子虚乌有", "黄金比例", "自树一帜"];
const CHAR_MAP = {
