            } else {
                defaultString += "????";
            }
        }

        return {
            data: defaultString
        }
    } else if (request.type === 2) {
        let inputString = request.answer;

        let input = [];
        for (let i = 0; i < 4; i++) {
            input[i] = [];
            for (let j = 0; j < 4; j++) {
                let char = inputString[i * 4 + j];
                if ((!CHAR_MAP[char]) && (char !== "?")) {
                    return {
                        error: "出现未知错误"
                    }
                }
                input[i][j] = char;
            }
        }

        let r1 = check1(input);
        let r2 = check2(input);
        let r3 = check3(input);
        let r4 = check4(input);

        let rs = ["", "", "", "", "", "", "", "", "", "", "", "", "", "", "", ""];
        for (let i = 0; i < 4; i++) {
            for (let j = 0; j < 4; j++) {
                rs[i * 4 + j] += r1.status[i][j];
                rs[i * 4 + j] += r2.status[i][j];
                rs[i * 4 + j] += r3.status[i][j];
                rs[i * 4 + j] += r4.status[i][j];
            }
        }

        let result = r1.result && r2.result && r3.result && r4.result;
        return {
            result: result,
            status: rs,
            message: result ? MESSAGE : undefined
        };
    }
    
    return {
        error: "type error"
    }
